using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace SoloCamera.Windows;
public sealed class LocalFeedServer:IDisposable {
 readonly TcpListener listener=new(IPAddress.Loopback,0);readonly CancellationTokenSource stop=new();readonly SemaphoreSlim requests=new(16);readonly PhoneConnection[] cameras;readonly string token=Convert.ToHexString(RandomNumberGenerator.GetBytes(24)).ToLowerInvariant();readonly byte[] page=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"feed.html"));
 public int Port{get;} public string Url=>$"http://127.0.0.1:{Port}/{token}/feed";public int Mode{get;set;}=-1;
 public LocalFeedServer(PhoneConnection[] cameras){this.cameras=cameras;listener.Start();Port=((IPEndPoint)listener.LocalEndpoint).Port;_=Task.Run(Accept);}
 async Task Accept(){try{while(!stop.IsCancellationRequested){var c=await listener.AcceptTcpClientAsync(stop.Token);if(!await requests.WaitAsync(0)){c.Dispose();continue;}_=Serve(c);}}catch when(stop.IsCancellationRequested){}}
 async Task Serve(TcpClient client){using(client)try{using var deadline=CancellationTokenSource.CreateLinkedTokenSource(stop.Token);deadline.CancelAfter(5000);var stream=client.GetStream();using var header=new MemoryStream();var one=new byte[1024];while(header.Length<8192){int count=await stream.ReadAsync(one,deadline.Token);if(count==0)return;header.Write(one,0,count);if(Encoding.ASCII.GetString(header.GetBuffer(),0,(int)header.Length).Contains("\r\n\r\n"))break;}var lines=Encoding.ASCII.GetString(header.ToArray()).Split("\r\n");var first=lines[0].Split(' ');int code=403;string type="text/plain",extra="";byte[] body=[];string prefix=$"/{token}/";if(first.Length==3&&first[0]=="GET"&&lines.Any(l=>l.Equals($"Host: 127.0.0.1:{Port}",StringComparison.OrdinalIgnoreCase))&&first[1].StartsWith(prefix,StringComparison.Ordinal)){string route=first[1].Split('?')[0][prefix.Length..];code=200;if(route=="feed"){body=page;type="text/html; charset=utf-8";}else if(route=="status"){body=JsonSerializer.SerializeToUtf8Bytes(new{mode=Mode,cameras=cameras.Select(c=>new{status=c.Status,frames=c.Frames,live=c.Latest is {} f&&(DateTime.UtcNow-f.At).TotalSeconds<2})});type="application/json";}else if(route.StartsWith("audio/")&&int.TryParse(route[6..],out int audioSlot)&&audioSlot>=0&&audioSlot<cameras.Length){long after=-1;string query=first[1].Contains('?')?first[1].Split('?',2)[1]:"";foreach(string item in query.Split('&'))if(item.StartsWith("after="))long.TryParse(item[6..],out after);var chunks=cameras[audioSlot].AudioAfter(after);if(chunks.Length==0)code=204;else{using var data=new MemoryStream();foreach(var chunk in chunks){byte[] h=new byte[24];System.Buffers.Binary.BinaryPrimitives.WriteInt64BigEndian(h,chunk.Sequence);System.Buffers.Binary.BinaryPrimitives.WriteInt64BigEndian(h.AsSpan(8),chunk.SourceUs);System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(h.AsSpan(16),chunk.Rate);System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(h.AsSpan(20),chunk.Pcm.Length);data.Write(h);data.Write(chunk.Pcm);}body=data.ToArray();type="application/octet-stream";}}else if(route.StartsWith("frame/")&&int.TryParse(route[6..],out int slot)&&slot>=0&&slot<cameras.Length){long after=-1;string query=first[1].Contains('?')?first[1].Split('?',2)[1]:"";foreach(string item in query.Split('&'))if(item.StartsWith("after="))long.TryParse(item[6..],out after);var f=after>=0?await cameras[slot].WaitForNewFrame(after,deadline.Token):cameras[slot].Latest;if(f==null||(DateTime.UtcNow-f.At).TotalSeconds>2)code=204;else{body=f.Jpeg;type="image/jpeg";extra=$"X-Rotation: {f.Rotation}\r\nX-Sequence: {f.Sequence}\r\nX-Time-Us: {f.SourceUs}\r\n";}}else code=404;}var headers=Encoding.ASCII.GetBytes($"HTTP/1.1 {code} Result\r\nContent-Length: {body.Length}\r\nContent-Type: {type}\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nConnection: close\r\n{extra}\r\n");await stream.WriteAsync(headers,deadline.Token);await stream.WriteAsync(body,deadline.Token);}catch{}finally{requests.Release();}}
 public void Dispose(){stop.Cancel();listener.Stop();}
}



